function kSmallestPairs(nums1, nums2, k) {
  const res = [];
  if (!nums1.length || !nums2.length || k === 0) return res;
  // Min-heap simulation with indices [i, j]
  // We push [nums1[i] + nums2[0], i, 0] for i = 0..min(k, nums1.length)-1
  const pq = [];
