  pq.sort((a, b) => a[0] - b[0]);
  while (pq.length > 0 && res.length < k) {
    const [sum, i, j] = pq.shift();
    res.push([nums1[i], nums2[j]]);
    if (j + 1 < nums2.length) {
      const nextItem = [nums1[i] + nums2[j + 1], i, j + 1];
      // Binary search insertion into sorted array to maintain heap property
