function lastStoneWeightII(stones) {
  // Recursion with all subset sums
  const total = stones.reduce((a, b) => a + b, 0);
  let minDiff = total;
  function backtrack(idx, curSum) {
    if (idx === stones.length) {
      minDiff = Math.min(minDiff, Math.abs(total - 2 * curSum));
      return;
    }
    backtrack(idx + 1, curSum + stones[idx]);
    backtrack(idx + 1, curSum);
  }
  backtrack(0, 0);
  return minDiff;
}

